fn largest_power_of_two_le(n: i8) -> i8 {
    // Start from the smallest power of two.
    let mut z: i8 = 1;
    // While doubling z keeps it ≤ n, do so.
    // Since we check z <= n/2, z*2 will never overflow or exceed n.
    while z <= n / 2 {
        z *= 2;
    }
    z
}

fn solve(n: i8) -> i8 {
    // If n is odd, return (n-1)/2 directly.
    if n % 2 != 0 {
        (n - 1) / 2
    } else {
        // Otherwise find the largest power-of-two z ≤ n,
        // then return (n - z) / 2.
        let z = largest_power_of_two_le(n);
        (n - z) / 2
    }
}

